import * as React from 'react';
import StepperContext from '../StepperContext';
import Connector, { MobileConnector } from '../Connector';
import { StepProps } from './StepTypes';
import StepContext from './StepContext';
import StepButton from '../StepButton';
import StepLabel from '../StepLabel';
import { MpaIcon } from "../../../index";
import '../Stepper.scss';
import clsx from 'clsx';
import useWindowSize from '../../../hooks/useWindowSize';
const Step: React.FC<StepProps> = ({
  children,
  label = '',
  completed: completedProp,
  active: activeProp,
  error: errorProp,
  disabled: disabledProp,
  className,
  index = 0,
  ...rest
}) => {
  const { activeStep,hideConnectors,buttonClassName,errorSteps } = React.useContext(StepperContext);

  let [active = false, completed = false, disabled = false,error = false] = [
    errorProp,
    activeProp,
    completedProp,
    disabledProp,
  ];

 const isInError = errorSteps.includes(index);
 error = errorProp ?? isInError;

  if (activeStep === index) {
    active = activeProp !== undefined ? activeProp : true;
  } else if (activeStep > index && !activeProp && !disabledProp && !isInError) {
    completed = completedProp !== undefined ? completedProp : true;
  } else if (activeStep < index && !activeProp && !completedProp) {
    disabled = disabledProp !== undefined ? disabledProp : true;
  }

  const contextValue = {
    error,
    completed,
    active,
    disabled,
    index,
  };

  let stepButtonClassNames = buttonClassName;
  if (!disabled && !completed) stepButtonClassNames += ` active`;
  if (completed) stepButtonClassNames += ` completed`;
  if (error) stepButtonClassNames += ` error`;
  if (className) stepButtonClassNames += ` ${className}`;

  const renderButtonContent = error ? (
      <MpaIcon iconName="ExclamationMark" size={20} />
  ) : completed ? (
      <MpaIcon iconName="Check" size={20} />
  ) : (
      children || index + 1
  );

  const { isMobile } = useWindowSize();
  return (
    <StepContext.Provider value={contextValue}>
      {index !== 0 && 
       ((hideConnectors === 'inactive' && (active || completed)) ||
       (hideConnectors !== true && hideConnectors !== 'inactive')) && (
       isMobile ? <MobileConnector /> : <Connector />
      )}
      <div id="mpa-StepMain" className={clsx("mpa-step-main", { "step-main-mobile": isMobile })}>
        <StepButton
          id="mpa-StepButton"
          className={stepButtonClassNames}
          {...rest}
        >
           {renderButtonContent}
        </StepButton>
        {label && (
          <StepLabel>
            {label}
          </StepLabel>
        )}
      </div>
    </StepContext.Provider>
  );
};

export default Step;
